                or "Qwen2-VL" in model_config["_name_or_path"]
                or "qwen2_vl" in model_config["_name_or_path"]
                or "qwen2_vl"
                in model_config["model_type"]  # new versions of Qwen was added
                or "Qwen2.5-VL" in model_config["_name_or_path"]
                or "qwen2.5_vl" in model_config["_name_or_path"]
                or "qwen2.5_vl" in model_config["model_type"]
            ):
