        response = list(response.split(example['sentence']))[-1].strip().split(temp_prompt)
        if len(response) > 1:
            response = response[1]
        else:
            response = response[0]


    response = response.strip().split("\n")[0]
    response = re.sub(r'[“”,."]', r'', response.strip())
    response = response.lower().strip()
    print("pred: ", response)
    label = all_labels [example['labels']]
    label = re.sub(r'[“”,."]', r'', label.strip())
    label = label.lower()
    print("labels: ", label)
    if response == label:
        correct += 1
    total += 1
    print("accuracy: ", correct/total)
    print("correct: ", correct)
    print("all: ", total)
    output_dict = {}
    output_dict['question'] = example['question']
    output_dict['sentence'] = example['sentence']
    output_dict['labels'] = label
    output_dict['pred'] = response
    feeds.append(output_dict)
    with open(output_file, mode='w', encoding='utf-8') as feedsjson:
        feedsjson.write(json.dumps(feeds, indent=2))

