class BaseAPI:
    def __init__(self, model_name: str, temperature: float = 0.0):
        self.model_name = model_name
        self.temperature = temperature
        self.acc_price = 0

    def run(self, prompt: str, img_path_list: List[str]) -> str:
        raise NotImplementedError("Subclasses should implement this method.")

    def get_acc_price(self) -> float:
        return self.acc_price


class InternVL(BaseAPI):
    def __init__(self, model_name: str, temperature: float = 0.0):
        super().__init__(model_name, temperature)
        if "InternVL2" in model_name:
            self.pipe = pipeline(model_name, backend_config=TurbomindEngineConfig(session_len=8192, tp=4))
        elif "InternVL3" in model_name:
            self.pipe = pipeline(model_name, backend_config=TurbomindEngineConfig(session_len=8192, tp=4), chat_template_config=ChatTemplateConfig(model_name='internvl2_5'))
        else:
            raise ValueError(f"Unknown model name: {model_name}")

    def run(self, prompt: str, img_path_list: List[str]) -> str:
        images = [load_image(img_url) for img_url in img_path_list]

        text = ""
        for i in range(len(img_path_list)):
            text += f"Image-{i + 1}: {IMAGE_TOKEN}\n"
        text += prompt

        response = self.pipe((text, images))
        return response.text


class Gemini(BaseAPI):
    prices = {
        "gemini-2.0-flash-lite": {"input": 0.075 * 1e-6, "output": 0.3 * 1e-6},
        "gemini-2.0-flash": {"input": 0.1 * 1e-6, "output": 0.4 * 1e-6},
        "gemini-2.5-flash": {"input": 0.15 * 1e-6, "output": 0.6 * 1e-6},
    }

    def __init__(self, model_name: str, temperature: float = 0.0):
        super().__init__(model_name, temperature)
        self.client = genai.Client(api_key=os.environ["GOOGLE_API_KEY"])

        self.input_price = 0
        self.output_price = 0
        for key in self.prices:
            if key in model_name:
                self.input_price = self.prices[key]["input"]
                self.output_price = self.prices[key]["output"]
                print(f"Gemini prices get: input={self.input_price}, output={self.output_price}")
                break

    def run(self, prompt: str, img_path_list: List[str]) -> str:
        img_list = [PIL.Image.open(img_path) for img_path in img_path_list]
        try:
            response = self.client.models.generate_content(
                model=self.model_name, contents=[prompt] + img_list,
                config = {"temperature": self.temperature}
            )
            input_tokens = response.usage_metadata.prompt_token_count
            output_tokens = response.usage_metadata.candidates_token_count

            self.acc_price += input_tokens * self.input_price + output_tokens * self.output_price
            return response.text
        except Exception as e:
            logging.info(f"ERROR at {img_path_list[0] if img_path_list else ''}:", e)
            time.sleep(10)
            return ""


class GPTs(BaseAPI):
    prices = {
        "gpt-4o": {"input": 2.5 * 1e-6, "output": 10 * 1e-6},
        "gpt-4o-20241120": {"input": 2.5 * 1e-6, "output": 10 * 1e-6},
    }

    def __init__(self, model_name: str, temperature: float = 0.0):
        super().__init__(model_name, temperature)
        self.client = OpenAI(api_key=os.environ["OPENAI_API_KEY"])

        self.input_price = self.prices.get(model_name, {}).get("input", 0)
        self.output_price = self.prices.get(model_name, {}).get("output", 0)
        print(f"GPT prices get: input={self.input_price}, output={self.output_price}")

    def encode_image(self, image_path: str) -> str:
        with open(image_path, "rb") as image_file:
            return base64.b64encode(image_file.read()).decode('utf-8')

    def run(self, prompt: str, img_path_list: List[str]) -> str:
        messages = [
            {
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": prompt,
                    }
                ],
            }
        ]

        for img_path in img_path_list:
            img = self.encode_image(img_path)
            messages[0]["content"].append(
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/jpeg;base64,{img}",
                    },
                }
            )

        try:
            response = self.client.chat.completions.create(
                model=self.model_name,
                temperature=self.temperature,
                messages=messages,
                max_tokens=8192,
            )
            input_tokens = response.usage.prompt_tokens
            output_tokens = response.usage.completion_tokens
            self.acc_price += input_tokens * self.input_price + output_tokens * self.output_price
            return response.choices[0].message.content
        except Exception as e:
            logging.info(f"ERROR at {img_path_list[0]}:", e)
            return ""


