class RemoteAPI(BaseAPI):
    model_dict = {
        "OpenGVLab/InternVL3-8B": "https://medical-infer.corp.ailabs.tw/internvl-3-14b/v1/chat/completions",
        "OpenGVLab/InternVL2_5-8B-MPO": "https://medical-infer.corp.ailabs.tw/internvl-2-5-8b-mpo/v1/chat/completions"
    }

    def __init__(self, model_name: str = "", temperature: float = 0.0):
        super().__init__(model_name, temperature)
        self.url = self.model_dict[model_name]
        self.headers = {
            "Content-Type": "application/json",
            "Authorization": "Bearer YOUR_API_KEY",  # remove this line if no auth
        }

    def encode_image(self, image_path: str) -> str:
        with open(image_path, "rb") as image_file:
            return base64.b64encode(image_file.read()).decode('utf-8')

    def run(self, prompt: str, img_path_list: List[str]) -> str:
        data = {
            "model": self.model_name,
            "messages": [
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": prompt},
                    ],
                }
            ],
            "temperature": self.temperature
        }

        for img_path in img_path_list:
            img = self.encode_image(img_path)
            data["messages"][0]["content"].append(
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/jpeg;base64,{img}",
                    },
                }
            )
        try:
            response = requests.post(self.url, headers=self.headers, json=data)
            response_dict = response.json()
            return response_dict['choices'][0]['message']['content']
        except Exception as e:
            logging.info(f"ERROR at {img_path_list[0]}:", e)
            return ""



def get_model(model_type: str, model_name: str, temperature: float = 0.0) -> tuple[BaseAPI, str]:
    if model_type == "internvl":
        model = InternVL(model_name, temperature)
        brev_name = f"{model_name.split('/')[-3].split('--')[-1]}"
    elif model_type == "google":
        model = Gemini(model_name, temperature)
        brev_name = model_name
    elif model_type == "openai":
        model = GPTs(model_name, temperature)
        brev_name = model_name
    elif model_type == "remote":
        model = RemoteAPI(model_name, temperature)
        brev_name = model_name.split('/')[-1]
    else:
        raise ValueError(f"Unknown model type: {model_type}")
    return model, brev_name

import os
