            response = response[1].split("service query")[0].strip()
        else:
            response = response[0].strip()
    response = response.strip().split("\n")[0]

    response = response.lower().strip()
    print("pred: ", response)
    label = all_labels[example['labels']]
    label = label.lower()
    print("labels: ", label)
