from .abstract_model import tp_model
import uuid,requests,time
from transformers import Qwen2VLForConditionalGeneration, AutoTokenizer, AutoProcessor
from PIL import Image
from typing import List
from qwen_vl_utils import process_vision_info
from lmdeploy import pipeline
from lmdeploy.vl import load_image


from .template_instruct import *
from ..utils.utils import *
from ..tool_inferencer.dynamic_batch_manager import DynamicBatchItem

from ..utils.log_utils import get_logger
inferencer_id = str(uuid.uuid4())[:6]
logger = get_logger("lmdeploy_model",)

class LMDeployModels(tp_model):
    def __init__(
      self,  
      pretrained : str = None,
    ):
        self.pipe = pipeline(pretrained)


    def generate_conversation_fn(
        self,
        text,
        image, 
        role = "user",
    ):  
        # import pdb; pdb.set_trace()
        text = fs_cota + "\n" + "Question: " + text

        image = pil_to_base64(image)
        messages=[
            {
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": text,
                    },
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": f"data:image/jpeg;base64,{image}"
                        },
                    },
                ],
            }
        ]

        return messages


    def append_conversation_fn(
        self, 
        conversation, 
        text, 
        image, 
        role
    ):
        if image:
            new_messages=[
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "text",
                            "text": text,
                        },
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": f"data:image/jpeg;base64,{image}"
                            },
                        },
                    ],
                }
            ]
        else:
            new_messages=[
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "text",
                            "text": text,
                        }
                    ],
                }
            ]

        conversation.extend(new_messages)

        return conversation


    def getitem_fn(self, meta_data, idx):
        item = meta_data[idx]
        image = Image.open(item["image_path"])
        text = item["text"]
        item_idx = item["idx"]
        res = dict(image=image, text=text, idx=item_idx)
        return res

    def form_input_from_dynamic_batch(self, batch: List[DynamicBatchItem]):
        if len(batch) == 0:
            return None
        messages = []
        for item in batch:
            messages.append(item.conversation)
        return messages

    def generate(self, batch):
        if not batch or len(batch) == 0:
            return
        max_new_tokens = self.generation_config.get("max_new_tokens", 2048)

        inputs = self.form_input_from_dynamic_batch(batch)
        response = self.pipe(inputs)


        for item, output_text in zip(batch, response):
            item.model_response.append(output_text)
            self.append_conversation_fn(
                item.conversation, output_text, None, "assistant"
            )

import json
import os.path

from mmengine.model import BaseModel

from lmdeploy import pipeline, TurbomindEngineConfig
from lmdeploy.vl import load_image
import torch
import torch.nn as nn

class MLLM_Annotor(BaseModel):
    def __init__(self,
        model=None,
        save_folder='./work_dirs/internvl72b_sam2_obj_cap/'
        ):
        super().__init__()
        print(torch.cuda.device_count())
        pipe = pipeline(model,
                        backend_config=TurbomindEngineConfig(
                            # session_len=8192,
                            session_len=16000,
                            tp=torch.cuda.device_count()),
                        )
        self.pipe = [pipe]
        self._zero = nn.Linear(10, 10)
        self.results_list = []
        self.item_idx = 0

        if not os.path.exists(save_folder):
            os.mkdir(save_folder)
        self.save_folder = save_folder

    def forward(self, **kwargs):
        return None

    def predict_forward_sam2(self, data_dicts):
        prompts = []
        for data_dict in data_dicts:
            images = data_dict['images']
            texts = data_dict['text_prompt']
            prompts.append((texts, images))

        response_list = self.pipe[0](prompts)
        text_lsit = [item.text for item in response_list]

        results_list = []

        for i, text in enumerate(text_lsit):
            if '图' in text or len(text) < 15:
                # wrong response
                continue
            results_list.append({
                'video_id': data_dicts[i]['video_id'],
                'obj_id': data_dicts[i]['obj_id'],
                'caption': text,
                'type': data_dicts[i]['type'],
            })
            # print('\n\n', results_list[-1], '\n\n')

        self.results_list += results_list

        if len(self.results_list) > 100:
            self.save_step()
            print("Saved !!!")

        return {}

    def predict_forward_sam2_recap(self, data_dicts):
        prompts = []
        for data_dict in data_dicts:
            images = data_dict['images']
            texts = data_dict['text_prompt']
            prompts.append((texts, images))

        response_list = self.pipe[0](prompts)
        text_lsit = [item.text for item in response_list]

        results_list = []

        for i, text in enumerate(text_lsit):
            if '图' in text or len(text) < 15:
